using System;using System.Collections.Concurrent;using System.Collections.Generic;using WildsEngine.Discoveries.Abstractions.Clusters;using WildsEngine.Discoveries.Abstractions.Narratives;using WildsEngine.Discoveries.Abstractions.Services;using WildsEngine.Discoveries.Abstractions.Surface;using WildsEngine.Discoveries.Narratives;
namespace WildsEngine.Discoveries.Surface { internal sealed class DiscoveryNarrativeSurface:IDiscoveryNarrativeSurface { private readonly IDiscoveryGeometrySurface _geometry;private readonly IDiscoveryRecognizedGeometryPopulationFactory _populations;private readonly IWildsServiceClock _clock;private readonly ConcurrentDictionary<Guid,IDiscoveryNarrativeProfile> _profiles=new ConcurrentDictionary<Guid,IDiscoveryNarrativeProfile>();private readonly ConcurrentDictionary<Guid,IDiscoveryNarrativeRegistration> _regs=new ConcurrentDictionary<Guid,IDiscoveryNarrativeRegistration>();public DiscoveryNarrativeSurface(IDiscoveryGeometrySurface g,IDiscoveryRecognizedGeometryPopulationFactory p,IWildsServiceClock c){_geometry=g;_populations=p;_clock=c;}public IDiscoveryRecognizedGeometryPopulation CreatePopulation(Guid id,IReadOnlyList<IDiscoveryClusterRecognitionResult> members){if(!_geometry.TryGetRegistration(id,out var r)||r==null)throw new KeyNotFoundException();return _populations.Create(r,members);}public IDiscoveryNarrativeRegistration Register(IDiscoveryNarrativeProfile p){if(p==null)throw new ArgumentNullException(nameof(p));if(!_profiles.TryAdd(p.Id,p))throw new InvalidOperationException("Narrative profile already registered.");var id=Guid.NewGuid();var r=new DiscoveryNarrativeRegistration(id,p,_clock.GetUtcNow());_regs[id]=r;return r;}public IDiscoveryNarrativeCompositionResult Compose(IDiscoveryRecognizedGeometryPopulation pop,Guid regId){if(pop==null)throw new ArgumentNullException(nameof(pop));if(!_regs.TryGetValue(regId,out var reg)||!_profiles.TryGetValue(reg.ProfileId,out var profile))throw new KeyNotFoundException();if(!string.Equals(pop.Scope,reg.Scope,StringComparison.Ordinal))throw new InvalidOperationException("Population and narrative registration scopes must match.");var groups=new List<List<IDiscoveryClusterRecognitionResult>>();foreach(var member in pop.Members){var placed=false;for(var g=0;g<groups.Count&&!placed;g++){for(var i=0;i<groups[g].Count;i++){var other=groups[g][i];var measure=profile.Metric.Measure(other,member);var rel=Find(profile,other.Mapping.SemanticKey,member.Mapping.SemanticKey);if(profile.CompositionPolicy.CanCompose(other,member,measure,rel)){groups[g].Add(member);placed=true;break;}}}if(!placed)groups.Add(new List<IDiscoveryClusterRecognitionResult>{member});}var output=new List<IDiscoveryNarrativeGroup>();foreach(var g in groups)output.Add(new DiscoveryNarrativeGroup(g));return new DiscoveryNarrativeCompositionResult(Guid.NewGuid(),pop,reg,output,_clock.GetUtcNow());}private static IDiscoveryNarrativeRelationshipDefinition? Find(IDiscoveryNarrativeProfile p,string a,string b){foreach(var r in p.Relationships)if((r.LeftSemanticKey==a&&r.RightSemanticKey==b)||(r.LeftSemanticKey==b&&r.RightSemanticKey==a))return r;return null;} } }
